import json
import sys
import os

def load_usage_state(filename):
    if os.path.exists(filename):
        with open(filename, 'r') as f:
            return json.load(f)
    return {}

def save_usage_state(filename, state):
    with open(filename, 'w') as f:
        json.dump(state, f)

def main(tokens_file):
    with open(tokens_file, 'r') as f:
        tokens_data = json.load(f)

    usage_state = load_usage_state('usage_state')
    output = []

    for line in sys.stdin:
        token = line.strip()
        if token not in tokens_data:
            output.append('DENY unknown')
            continue

        user_info = tokens_data[token]
        user = user_info['user']
        limit = user_info['limit']
        current_count = usage_state.get(user, 0)

        if current_count >= limit:
            output.append(f'DENY {user}')
        else:
            usage_state[user] = current_count + 1
            output.append(f'ALLOW {user}')

    save_usage_state('usage_state', usage_state)
    print('\n'.join(output))

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python quota_check.py TOKENS_FILE')
        sys.exit(1)
    main(sys.argv[1])

