import json
import os
import sys

def load_usage_state():
    if os.path.exists("usage_state"):
        with open("usage_state", "r") as f:
            return json.load(f)
    return {}

def save_usage_state(state):
    with open("usage_state", "w") as f:
        json.dump(state, f)

def load_tokens(tokens_file):
    with open(tokens_file, "r") as f:
        return json.load(f)

def process_tokens(tokens_file):
    tokens = load_tokens(tokens_file)
    state = load_usage_state()

    for line in sys.stdin:
        token = line.strip()
        if not token:
            continue

        if token not in tokens:
            print(f"DENY unknown")
            continue

        user = tokens[token]["user"]
        if state.get(user, 0) >= tokens[token]["limit"]:
            print(f"DENY {user}")
        else:
            state[user] = state.get(user, 0) + 1
            print(f"ALLOW {user}")

    save_usage_state(state)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python quota_check.py TOKENS_FILE", file=sys.stderr)
        sys.exit(1)
    process_tokens(sys.argv[1])

